SELECT t_maintaining_record.*
FROM t_maintaining_record

    deleted_flag = #{queryForm.deletedFlag}

        AND DATE_FORMAT(ret_maintainence_date, '%Y-%m-%d') >= #{queryForm.retMaintainenceDateStartTime}


        AND DATE_FORMAT(ret_maintainence_date, '%Y-%m-%d') <= #{queryForm.retMaintainenceDateEndTime}


        AND INSTR(sprinkler_serial,#{queryForm.sprinklerSerial})



        AND INSTR(ret_maintainence_reason,#{queryForm.retMaintainenceReason})



        AND INSTR(real_reason,#{queryForm.realReason})



        AND INSTR(customer,#{queryForm.customer})



        AND DATE_FORMAT(ret_warehouse_date, '%Y-%m-%d') >= #{queryForm.retWarehouseDateStartTime}


        AND DATE_FORMAT(ret_warehouse_date, '%Y-%m-%d') <= #{queryForm.retWarehouseDateEndTime}



        AND INSTR(ret_warehouse_type,#{queryForm.retWarehouseType})



        AND INSTR(allocate_limitation,#{queryForm.allocateLimitation})



        AND disabled_flag = #{queryForm.disabledFlag}



    ORDER BY create_time DESC

SELECT mr.*
FROM t_maintaining_record mr
WHERE mr.record_id = #{recordId} AND mr.deleted_flag = #{deletedFlag}
